@runner.on("job:assigned", namespace="/runner") async def on_assigned(payload: dict) -> None: assigned_payload.update(payload) assigned.set()
@ui.on("captcha:required", namespace="/ui") async def on_captcha(_payload: dict) -> None: captcha_visible.set()
@runner.on("captcha:submit", namespace="/runner") async def on_captcha_submitted(_payload: dict) -> None: captcha_forwarded.set() return {"ok": True}
@runner.on("captcha:refresh", namespace="/runner") async def on_captcha_refresh(payload: dict) -> dict: assert payload["captchaId"] == "captcha-sequence-refreshed" captcha_refresh_forwarded.set() acknowledgement = await runner.call( "captcha:refreshed", { "jobId": payload["jobId"], "captchaId": "captcha-sequence-manual-refresh", "imageDataUrl": "data:image/png;base64,iVBORw0KGgo=", }, namespace="/runner", timeout=2, ) assert acknowledgement["ok"] is True return {"ok": True}
@runner.on("runner:options", namespace="/runner") async def on_runner_options(payload: dict) -> dict: assert payload["type"] == "GET_ALL_OPTIONS" return {"ok": True, "options": {"states": ["Delhi"]}}
@ui.on("captcha:invalid", namespace="/ui") async def on_captcha_invalid(_payload: dict) -> None: captcha_invalid_visible.set()
@ui.on("captcha:refreshed", namespace="/ui") async def on_captcha_refreshed(_payload: dict) -> None: captcha_refreshed_visible.set()
@ui.on("job:status", namespace="/ui") async def on_job_status(payload: dict) -> None: if payload.get("status") == "FAILED": failed_payload.update(payload) captcha_failed_visible.set()
